tests_src:
def test_definition_conditions(run, x):
    n = int(x.strip())
    out = run(x)
    h = int(out.strip())
    total_h = h * (h + 1) * (h + 2) // 6
    total_h1 = (h + 1) * (h + 2) * (h + 3) // 6
    assert total_h <= n < total_h1

def test_bruteforce_sum(run, x):
    n = int(x.strip())
    out = run(x)
    h_out = int(out.strip())
    h = 0
    total = 0
    while True:
        next_level = (h + 1) * (h + 2) // 2
        if total + next_level <= n:
            total += next_level
            h += 1
        else:
            break
    assert h == h_out

def test_examples(run, x):
    n = int(x.strip())
    out = run(x).strip()
    if n == 1:
        assert out == "1"
    elif n == 2:
        assert out == "1"
    elif n == 25:
        assert out == "4"

def test_output_format(run, x):
    out = run(x)
    s = out.rstrip('\n')
    assert s.isdigit()
    assert out == s + '\n'

def test_answer_positive(run, x):
    n = int(x.strip())
    out = run(x)
    h = int(out.strip())
    assert h >= 1

def test_answer_less_than_n(run, x):
    n = int(x.strip())
    out = run(x)
    h = int(out.strip())
    assert h <= n

def test_monotonic(run, x):
    n = int(x.strip())
    out = run(x)
    h = int(out.strip())
    def max_height(m):
        ht = 0
        total = 0
        while True:
            next_level = (ht + 1) * (ht + 2) // 2
            if total + next_level <= m:
                total += next_level
                ht += 1
            else:
                break
        return ht
    if n > 1:
        h_prev = max_height(n - 1)
        assert h_prev <= h
    h_next = max_height(n + 1)
    assert h <= h_next

def test_step_increase(run, x):
    n = int(x.strip())
    out = run(x)
    h = int(out.strip())
    def max_height(m):
        ht = 0
        total = 0
        while True:
            next_level = (ht + 1) * (ht + 2) // 2
            if total + next_level <= m:
                total += next_level
                ht += 1
            else:
                break
        return ht
    if n > 1:
        h_prev = max_height(n - 1)
        assert h == h_prev or h == h_prev + 1

def test_boundary_max(run, x):
    n = int(x.strip())
    if n == 10000:
        out = run(x)
        h = int(out.strip())
        correct = 0
        total = 0
        while True:
            next_level = (correct + 1) * (correct + 2) // 2
            if total + next_level <= n:
                total += next_level
                correct += 1
            else:
                break
        assert h == correct

def test_tetrahedral_boundaries(run, x):
    n = int(x.strip())
    out = run(x)
    h = int(out.strip())
    def is_tetrahedral(num):
        # return height h if num = T(h), else None
        # approximate cube root
        if num <= 0:
            return None
        approx = int((6 * num) ** (1/3))
        for cand in range(max(1, approx - 2), approx + 3):
            if cand * (cand + 1) * (cand + 2) // 6 == num:
                return cand
        return None
    tetra = is_tetrahedral(n)
    if tetra is not None:
        assert h == tetra
    else:
        tetra_next = is_tetrahedral(n + 1)
        if tetra_next is not None:
            assert h == tetra_next - 1

