def test_output_is_integer(run, x):
    output = run(x)
    try:
        h = int(output.strip())
    except ValueError:
        assert False, "Output is not an integer"

def test_output_positive(run, x):
    output = run(x)
    try:
        h = int(output.strip())
    except ValueError:
        assert False, "Output is not an integer"
    assert h >= 1, "Height must be at least 1"

def test_output_upper_bound(run, x):
    output = run(x)
    try:
        h = int(output.strip())
    except ValueError:
        assert False, "Output is not an integer"
    assert h <= 50, f"Height {h} exceeds reasonable maximum"

def test_h_le_n(run, x):
    n = int(x.strip())
    output = run(x)
    try:
        h = int(output.strip())
    except ValueError:
        assert False, "Output is not an integer"
    assert h <= n, f"Height {h} exceeds number of cubes {n}"

def test_total_cubes_not_exceeded(run, x):
    n = int(x.strip())
    output = run(x)
    try:
        h = int(output.strip())
    except ValueError:
        assert False, "Output is not an integer"
    S = h * (h + 1) * (h + 2) // 6
    assert S <= n, f"Total cubes needed for height {h} is {S} > {n}"

def test_cannot_build_next_level(run, x):
    n = int(x.strip())
    output = run(x)
    try:
        h = int(output.strip())
    except ValueError:
        assert False, "Output is not an integer"
    S_next = (h + 1) * (h + 2) * (h + 3) // 6
    assert S_next > n, f"Can build height {h+1} needing {S_next} <= {n}"

def test_example1(run, x):
    output = run(x)
    if x == "1\n":
        try:
            h = int(output.strip())
        except ValueError:
            assert False, "Output is not an integer"
        assert h == 1, f"For n=1, expected 1, got {h}"

def test_brute_force_oracle(run, x):
    n = int(x.strip())
    output = run(x)
    try:
        h_out = int(output.strip())
    except ValueError:
        assert False, "Output is not an integer"
    h = 0
    while True:
        if (h + 1) * (h + 2) * (h + 3) // 6 > n:
            break
        h += 1
    assert h_out == h, f"Expected height {h}, got {h_out}"

def test_consistency_simulation(run, x):
    n = int(x.strip())
    output = run(x)
    try:
        h = int(output.strip())
    except ValueError:
        assert False, "Output is not an integer"
    total = 0
    for i in range(1, h + 1):
        total += i * (i + 1) // 2
        if total > n:
            assert False, f"During simulation, exceeded n at level {i}"
    next_level = (h + 1) * (h + 2) // 2
    if total + next_level <= n:
        assert False, f"Could build one more level, total would be {total + next_level} <= {n}"

def test_tetrahedral_numbers(run, x):
    n = int(x.strip())
    output = run(x)
    try:
        h_out = int(output.strip())
    except ValueError:
        assert False, "Output is not an integer"
    for h in range(1, 50):
        if h * (h + 1) * (h + 2) // 6 == n:
            assert h_out == h, f"For tetrahedral number n={n}, expected height {h}, got {h_out}"
            return
